using System;using System.Collections.Generic;public class RandomizedSet{List<int>a=new();Dictionary<int,int>m=new();Random r=new();public RandomizedSet(){}public bool Insert(int v){if(m.ContainsKey(v))return false;m[v]=a.Count;a.Add(v);return true;}public bool Remove(int v){if(!m.ContainsKey(v))return false;int i=m[v],x=a[^1];a[i]=x;m[x]=i;a.RemoveAt(a.Count-1);m.Remove(v);return true;}public int GetRandom()=>a[r.Next(a.Count)];}
